require_once __DIR__ . '/../../../vendor/autoload.php';

use Facebook\WebDriver\Chrome\ChromeOptions;
use Facebook\WebDriver\Remote\DesiredCapabilities;
use Facebook\WebDriver\Remote\RemoteWebDriver;
use Facebook\WebDriver\WebDriverBy;
use Facebook\WebDriver\WebDriverExpectedCondition;
use Facebook\WebDriver\WebDriverWait;
use Facebook\WebDriver\WebDriverDimension;

class SchoolManagementSystemTest
{
    private $driver;
    private $baseUrl = 'http://localhost/research/sms/SMS_Semi-Automated/';

    public function setUp(): void
    {
        $host = 'http://localhost:50843'; // Change this if ChromeDriver runs on another port

        $options = new ChromeOptions();
        $options->setBinary('C:\Program Files\Google\Chrome\Application\chrome.exe');
        $options->addArguments(['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu', '--window-size=1920,1080']);

        $capabilities = DesiredCapabilities::chrome();
        $capabilities->setCapability(ChromeOptions::CAPABILITY, $options);

        $this->driver = RemoteWebDriver::create($host, $capabilities);
        $this->driver->manage()->window()->maximize();
    }

    public function tearDown(): void
    {
        if ($this->driver) {
            try {
                $this->driver->quit();
            } catch (Exception $e) {
                // The browser may already have closed after a WebDriver failure.
            }
            $this->driver = null;
        }
    }

    private function waitForLoginModal(): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::visibilityOfElementLocated(WebDriverBy::id('loginFrom')));
        $wait->until(WebDriverExpectedCondition::visibilityOfElementLocated(WebDriverBy::id('email')));
        $wait->until(WebDriverExpectedCondition::visibilityOfElementLocated(WebDriverBy::id('password')));
        $wait->until(WebDriverExpectedCondition::elementToBeClickable(WebDriverBy::id('btnSubmit')));
    }

    private function clickElementWhenReady(WebDriverBy $locator): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::elementToBeClickable($locator));
        $element = $this->driver->findElement($locator);

        try {
            $element->click();
        } catch (Exception $e) {
            $this->driver->executeScript('arguments[0].click();', [$element]);
        }
    }

    private function loginAs(string $email, string $password, ?string $expectedDashboard = null): void
    {
        $this->driver->get($this->baseUrl . 'index.php');
        $this->waitForLoginModal();

        $emailElement = $this->driver->findElement(WebDriverBy::id('email'));
        $passwordElement = $this->driver->findElement(WebDriverBy::id('password'));

        $emailElement->clear()->sendKeys($email);
        $passwordElement->clear()->sendKeys($password);

        sleep(2);
        $this->clickElementWhenReady(WebDriverBy::id('btnSubmit'));

        $this->waitForLoginResult();
        if ($expectedDashboard !== null) {
            $wait = new WebDriverWait($this->driver, 20);
            try {
                $wait->until(WebDriverExpectedCondition::urlContains($expectedDashboard));
            } catch (Exception $e) {
                throw new RuntimeException(
                    'Expected dashboard ' . $expectedDashboard . ' but reached ' . $this->driver->getCurrentURL()
                );
            }
        }
    }

    private function waitForSignOutLink(): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::cssSelector('.dropdown.user.user-menu > a.dropdown-toggle')));
    }

    private function openUserMenu(): void
    {
        $this->clickElementWhenReady(WebDriverBy::cssSelector('.dropdown.user.user-menu > a.dropdown-toggle'));
    }

    private function clickSignOut(): void
    {
        $this->openUserMenu();
        sleep(2);
        $this->clickElementWhenReady(WebDriverBy::cssSelector('a[href="login.php"]'));
    }

    private function waitForLoginResult(): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        try {
            $wait->until(function () {
                $url = $this->driver->getCurrentURL();
                return strpos($url, 'view/dashboard') !== false
                    || strpos($url, 'view/login.php') !== false;
            });
        } catch (Exception $e) {
            throw new RuntimeException(
                'Login did not redirect. Current URL: ' . $this->driver->getCurrentURL()
            );
        }
    }

    private function waitForDashboardHeading(): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::xpath("//section[contains(@class,'content-header')]//h1[contains(normalize-space(.),'Dashboard') or contains(normalize-space(.),'Dashboard')]")));
    }

    private function waitForDashboardInfoBox(string $text): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::xpath("//span[contains(@class,'info-box-text') and normalize-space(text())='$text']")));
    }

    private function goToClassroomPage(): void
    {
        $this->waitForSignOutLink();
        $this->waitForDashboardHeading();
        $this->clickElementWhenReady(WebDriverBy::cssSelector('a[href="class_room.php"]'));
        $this->waitForClassroomPage();
    }

    private function waitForClassroomPage(): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::urlContains('view/class_room.php'));
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::xpath("//h1[contains(normalize-space(.),'Classroom')]") ));
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::id('example1')));
    }

    private function waitForClassroomRow(string $name): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::xpath("//table[@id='example1']//tr[.//td[normalize-space(text())='$name']]")));
    }

    private function waitForClassroomNoRow(string $name): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(function () use ($name) {
            $rows = $this->driver->findElements(WebDriverBy::xpath("//table[@id='example1']//tr[.//td[normalize-space(text())='$name']]"));
            return count($rows) === 0;
        });
    }

    private function clickEditClassroomByName(string $name): void
    {
        $this->clickElementWhenReady(WebDriverBy::xpath("//table[@id='example1']//tr[.//td[normalize-space(text())='$name']]//a[contains(normalize-space(.),'Edit')]"));
    }

    private function deleteClassroomByName(string $name): void
    {
        $this->clickElementWhenReady(WebDriverBy::xpath("//table[@id='example1']//tr[.//td[normalize-space(text())='$name']]//a[contains(@class,'confirm-delete')]"));
        $this->clickElementWhenReady(WebDriverBy::id('btnYes'));
        $this->waitForClassroomNoRow($name);
    }

    private function createUniqueClassroomName(): string
    {
        return 'CR_' . time() . '_' . rand(1000, 9999);
    }

    private function waitForModalVisible(string $modalId): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::visibilityOfElementLocated(WebDriverBy::id($modalId)));
    }

    private function waitForModalHidden(string $modalId): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::invisibilityOfElementLocated(WebDriverBy::id($modalId)));
    }

    private function verifySidebarItems(array $items): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        foreach ($items as $item) {
            $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(
                WebDriverBy::xpath("//span[contains(normalize-space(text()),'{$item}')]")
            ));
        }
    }

    private function navigateToMenuPage(string $pageLink): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::elementToBeClickable(WebDriverBy::cssSelector("a[href='{$pageLink}']")));
        $this->clickElementWhenReady(WebDriverBy::cssSelector("a[href='{$pageLink}']"));
        sleep(2);
    }

    private function verifyDashboardMenuPages(array $pages, string $dashboardPath): void
    {
        foreach ($pages as $pageLink => $pageTitle) {
            $this->navigateToMenuPage($pageLink);
            $this->verifyPageLoaded($pageTitle);
            echo "  ✓ {$pageTitle} page accessible\n";

            $this->returnToDashboard($dashboardPath);
            $this->waitForDashboardHeading();
        }
    }

    private function verifyTreeviewMenuPages(array $menus, string $dashboardPath): void
    {
        foreach ($menus as $menu) {
            $this->clickTreeviewLink($menu['group'], $menu['link']);
            $this->verifyPageLoaded($menu['title']);
            echo "  ✓ {$menu['title']} page accessible\n";

            $this->returnToDashboard($dashboardPath);
            $this->waitForDashboardHeading();
        }
    }

    private function returnToDashboard(string $dashboardPath): void
    {
        $dashboardFile = basename($dashboardPath);
        $this->clickElementWhenReady(WebDriverBy::cssSelector("a[href='{$dashboardFile}']"));
        (new WebDriverWait($this->driver, 20))->until(
            WebDriverExpectedCondition::urlContains($dashboardPath)
        );
    }

    private function verifyEmployeeCrudAccess(): void
    {
        $this->navigateToMenuPage('teacher.php');
        $this->verifyPageLoaded('Teacher');
        (new WebDriverWait($this->driver, 20))->until(
            WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::id('form1'))
        );
        echo "  ✓ Employee create form accessible\n";

        $this->returnToDashboard('view/dashboard.php');
        $this->waitForDashboardHeading();
        $this->openEmployeeListPage();
        $this->verifyPageLoaded('Teacher');
        (new WebDriverWait($this->driver, 20))->until(
            WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::id('example1'))
        );
        (new WebDriverWait($this->driver, 20))->until(
            WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::cssSelector('.confirm-delete'))
        );
        (new WebDriverWait($this->driver, 20))->until(
            WebDriverExpectedCondition::presenceOfElementLocated(WebDriverBy::xpath("//a[contains(normalize-space(.),'Edit')]") )
        );
        echo "  ✓ Employee edit and delete controls accessible\n";
    }

    private function openEmployeeListPage(): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $link = WebDriverBy::cssSelector('a[href="all_teacher.php"]');
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated($link));
        $this->driver->executeScript('window.location.href = arguments[0];', ['all_teacher.php']);
        $wait->until(WebDriverExpectedCondition::urlContains('view/all_teacher.php'));
    }
    private function clickTreeviewLink(string $treeviewSpanText, string $submenuLink): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        // Find and click the treeview header
        $header = WebDriverBy::xpath("//span[normalize-space(text())='{$treeviewSpanText}']/parent::a");
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated($header));
        $this->driver->executeScript('arguments[0].click();', [$this->driver->findElement($header)]);
        sleep(1);
        // Then click the submenu link
        $submenu = WebDriverBy::cssSelector("a[href='{$submenuLink}']");
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated($submenu));
        $this->driver->executeScript('arguments[0].click();', [$this->driver->findElement($submenu)]);
        sleep(2);
    }
    private function verifyPageLoaded(string $pageTitle): void
    {
        $wait = new WebDriverWait($this->driver, 20);
        $wait->until(WebDriverExpectedCondition::presenceOfElementLocated(
            WebDriverBy::xpath("//h1[contains(normalize-space(text()),'{$pageTitle}')] | //section[contains(@class,'content-header')]//h1")
        ));
    }

