    public function testResponsiveDesign(): void
    {
        echo "Running testResponsiveDesign...\n";
        $this->driver->get($this->baseUrl . 'index.php');
        $this->waitForLoginModal();

        $sizes = [
            [375, 667],
            [768, 1024],
            [1920, 1080],
        ];

        foreach ($sizes as $size) {
            $this->driver->manage()->window()->setSize(new WebDriverDimension($size[0], $size[1]));
            sleep(1);
            assert(strlen($this->driver->getPageSource()) > 0, 'Login page should render at ' . $size[0] . 'x' . $size[1]);
        }

        sleep(2);
        echo "✓ Test Case 17: Responsive login page renders at mobile, tablet, desktop widths\n";
    }

    public function runAllTests(): void
    {
        echo "Starting SMS Selenium test suite...\n\n";

        $tests = [
            'testLoginPageDisplays',
            'testInvalidLogin',
            'testAdminLoginAndAccess',        
            'testAdminEmployeeCrudAccess',
            'testTenantLoginAndAccess',
            'testEmployeeLoginAndAccess',
            'testOwnerLoginAndAccess',
            'testSignOutReturnsToLogin',
            'testResponsiveDesign',
        ];

        foreach ($tests as $test) {
            try {
                $this->setUp();
                $this->$test();
                $this->tearDown();
                echo "\n";
            } catch (Exception $e) {
                $details = $e->getMessage();
                if ($details === '') {
                    $details = get_class($e);
                }
                if ($this->driver) {
                    try {
                        $details .= ' | URL: ' . $this->driver->getCurrentURL();
                    } catch (Exception $driverException) {
                        $details .= ' | Browser session unavailable';
                    }
                }
                echo "✗ $test failed: " . $details . "\n\n";
                $this->tearDown();
            }
        }
        sleep(2);
        echo "SMS Selenium test suite completed!\n";
    }
}

$testSuite = new SchoolManagementSystemTest();
$testSuite->runAllTests();
